public static MecabDictionary load(Path directory, Charset charset) throws IOException {
    if (directory == null) {
      throw new IllegalArgumentException("directory must not be null");
    }
    if (charset == null) {
      throw new IllegalArgumentException("charset must not be null");
    }
    // The connection matrix is read first because its dimensions are what every
    // lexicon entry's context ids have to be inside of.
    final Path matrixFile = directory.resolve(MATRIX_DEF);
    if (!Files.exists(matrixFile)) {
      throw new IOException("required dictionary file is missing: " + matrixFile);
    }
    final int leftSize;
    final int rightSize;
    final short[] costs;
    final int cellCount;
    try (BufferedReader reader = Files.newBufferedReader(matrixFile, charset)) {
      final String rawHeader = reader.readLine();
      if (rawHeader == null) {
        throw new IOException("empty " + MATRIX_DEF + " under " + directory);
      }
      final String headerLine = StringUtil.trimUnicodeWhitespace(rawHeader);
      if (headerLine.isEmpty()) {
        throw new IOException("empty " + MATRIX_DEF + " under " + directory);
      }
      final String[] header = splitWhitespace(headerLine);
      if (header.length != 2) {
        throw new IOException("malformed " + MATRIX_DEF + " header: " + headerLine);
      }
      leftSize = parseInt(header[0], MATRIX_DEF, 1);
      rightSize = parseInt(header[1], MATRIX_DEF, 1);
      if (leftSize < 1 || rightSize < 1) {
        throw new IOException(MATRIX_DEF + " dimensions must be positive, got "
            + leftSize + " " + rightSize);
      }
      if (leftSize > ResourceLimits.MAX_ENTRIES
          || rightSize > ResourceLimits.MAX_ENTRIES) {
        throw new IOException(MATRIX_DEF + " dimensions " + leftSize + " x " + rightSize
            + " exceed safe limit of " + ResourceLimits.MAX_ENTRIES);
      }
      final long cells = (long) leftSize * rightSize;
      if (cells > Integer.MAX_VALUE) {
        throw new IOException(MATRIX_DEF + " dimensions " + leftSize + " x " + rightSize
            + " overflow the addressable connection matrix");
      }
      if (cells > ResourceLimits.MAX_MATRIX_CELLS) {
        throw new IOException(MATRIX_DEF + " dimensions " + leftSize + " x " + rightSize
            + " exceed safe limit of " + ResourceLimits.MAX_MATRIX_CELLS);
      }
      cellCount = (int) cells;
      costs = new short[cellCount];
      // leftSize bounds right-context ids and rightSize bounds left-context ids, matching
      // MeCab's connector.h layout (the names read transposed against the id names).
      final BitSet filled = new BitSet(cellCount);
      int lineNumber = 1;
      String raw;
      while ((raw = reader.readLine()) != null) {
        lineNumber++;
        final String line = StringUtil.trimUnicodeWhitespace(raw);
        if (line.isEmpty()) {
          continue;
        }
        final String[] fields = splitWhitespace(line);
        if (fields.length != 3) {
          throw new IOException("malformed " + MATRIX_DEF + " line " + lineNumber);
        }
        final int right = parseInt(fields[0], MATRIX_DEF, lineNumber);
        final int left = parseInt(fields[1], MATRIX_DEF, lineNumber);
        if (right < 0 || right >= leftSize || left < 0 || left >= rightSize) {
          throw new IOException("malformed " + MATRIX_DEF + " line " + lineNumber
              + ": context ids " + right + " " + left
              + " are outside the declared dimensions " + leftSize + " " + rightSize);
        }
        final int cost = parseInt(fields[2], MATRIX_DEF, lineNumber);
        if (cost < Short.MIN_VALUE || cost > Short.MAX_VALUE) {
          throw new IOException("malformed " + MATRIX_DEF + " line " + lineNumber
              + ": connection cost " + cost + " is outside the 16-bit range the"
              + " format defines");
        }
        final int index = right * rightSize + left;
        if (filled.get(index)) {
          throw new IOException("duplicate " + MATRIX_DEF + " entry " + right + " "
              + left + " at line " + lineNumber);
        }
        costs[index] = (short) cost;
        filled.set(index);
      }
      if (filled.cardinality() != cellCount) {
        throw new IOException(MATRIX_DEF + " declares " + leftSize + " x " + rightSize
            + " connection costs but only " + filled.cardinality()
            + " pairs are listed");
      }
    }

    final Map<String, List<WordEntry>> lexicon = new HashMap<>();
    final List<Path> csvFiles = new ArrayList<>();
    try (DirectoryStream<Path> stream = Files.newDirectoryStream(directory, LEXICON_GLOB)) {
      for (final Path csv : stream) {
        csvFiles.add(csv);
      }
    }
    Collections.sort(csvFiles);
    final int[] entryCount = {0};
    for (final Path csv : csvFiles) {
      readLexicon(csv, charset, lexicon, leftSize, rightSize, entryCount);
    }
    if (lexicon.isEmpty()) {
      throw new IOException("no lexicon entries found under " + directory);
    }

    final Map<String, Category> categories = new HashMap<>();
    final CategoryTable.Builder categoryTable = new CategoryTable.Builder();
    readCharacterDefinition(directory.resolve(CHAR_DEF), charset, categories,
        categoryTable);
    final Map<String, List<WordEntry>> unknown = new HashMap<>();
    final Path unkFile = directory.resolve(UNK_DEF);
    readLexicon(unkFile, charset, unknown, leftSize, rightSize, new int[] {0});
    for (final String category : unknown.keySet()) {
      if (!categories.containsKey(category)) {
        throw new IOException(
            UNK_DEF + " names the undefined category " + category + ": " + unkFile);
      }
    }

    return new MecabDictionary(DoubleArrayLexicon.build(lexicon), costs,
        rightSize, categories, categoryTable.build(categories), unknown);
  }

@Override
  public int distance(CharSequence a, CharSequence b, int max) {
    if (a == null || b == null) {
      throw new IllegalArgumentException("input sequences must not be null");
    }
    if (max < 0) {
      throw new IllegalArgumentException("max must not be negative: " + max);
    }

    int[] s1 = CodePoints.of(a);
    int[] s2 = CodePoints.of(b);

    // Keep the shorter string as the columns to minimise memory.
    if (s1.length > s2.length) {
      final int[] tmp = s1;
      s1 = s2;
      s2 = tmp;
    }

    int len1 = s1.length;
    int len2 = s2.length;

    // Trim the common suffix; it contributes nothing to the distance.
    while (len1 > 0 && s1[len1 - 1] == s2[len2 - 1]) {
      len1--;
      len2--;
    }

    // Trim the common prefix.
    int offset = 0;
    while (offset < len1 && s1[offset] == s2[offset]) {
      offset++;
    }
    len1 -= offset;
    len2 -= offset;

    if (len1 == 0) {
      return len2 <= max ? len2 : -1;
    }
    // Minimum possible distance is the length difference.
    if (len2 - len1 > max) {
      return -1;
    }

    // prev = row i-1, cur = row i, before = row i-2 (for transpositions).
    final int[] prev = new int[len1 + 1];
    final int[] cur = new int[len1 + 1];
    final int[] before = new int[len1 + 1];
    for (int j = 0; j <= len1; j++) {
      prev[j] = j;
    }

    for (int i = 1; i <= len2; i++) {
      final int c2 = s2[offset + i - 1];
      cur[0] = i;
      int rowMin = cur[0];
      final int prevC2 = i >= 2 ? s2[offset + i - 2] : -1;

      for (int j = 1; j <= len1; j++) {
        final int c1 = s1[offset + j - 1];
        final int cost = (c1 == c2) ? 0 : 1;
        int value = CodePoints.min3(
            prev[j] + 1,        // deletion
            cur[j - 1] + 1,     // insertion
            prev[j - 1] + cost  // substitution / match
        );
        if (i >= 2 && j >= 2 && c1 == prevC2 && s1[offset + j - 2] == c2) {
          value = Math.min(value, before[j - 2] + 1); // transposition
        }
        cur[j] = value;
        if (value < rowMin) {
          rowMin = value;
        }
      }

      if (rowMin > max) {
        return -1;
      }

      // Rotate rows: before <- prev <- cur, and reuse 'before' array as next 'cur'.
      System.arraycopy(prev, 0, before, 0, len1 + 1);
      System.arraycopy(cur, 0, prev, 0, len1 + 1);
    }

    final int result = prev[len1];
    return result <= max ? result : -1;
  }

public static SvmDoccatModel train(String lang,
                                     ObjectStream<DocumentSample> samples,
                                     SvmDoccatConfiguration config,
                                     FeatureGenerator... featureGenerators) throws IOException {
    Objects.requireNonNull(samples, "samples must not be null");
    Objects.requireNonNull(config, "config must not be null");
    Objects.requireNonNull(featureGenerators, "featureGenerators must not be null");
    if (featureGenerators.length == 0) {
      throw new IllegalArgumentException("At least one FeatureGenerator is required");
    }

    // --- Pass 1: Collect all samples, build vocabulary + category mappings ---
    Map<String, Integer> categoryToIndex = new LinkedHashMap<>();
    Map<Integer, String> indexToCategory = new HashMap<>();
    List<DocumentSample> allSamples = new ArrayList<>();

    // Per-document: feature string set and term frequency map
    List<Set<String>> docFeatureSets = new ArrayList<>();
    List<Map<String, Integer>> docTfMaps = new ArrayList<>();
    List<String> docLabels = new ArrayList<>();

    // Corpus-level document frequency
    Map<String, Integer> documentFrequency = new HashMap<>();
    int totalDocs = 0;

    DocumentSample sample;
    while ((sample = samples.read()) != null) {
      allSamples.add(sample);
      totalDocs++;

      // Register category
      String category = sample.getCategory();
      if (!categoryToIndex.containsKey(category)) {
        int catIdx = categoryToIndex.size();
        categoryToIndex.put(category, catIdx);
        indexToCategory.put(catIdx, category);
      }
      docLabels.add(category);

      // Extract features
      String[] context = generateContext(sample.getText(), sample.getExtraInformation(),
          featureGenerators);

      // Compute term frequency for this document
      Map<String, Integer> tf = new HashMap<>();
      for (String feature : context) {
        tf.merge(feature, 1, Integer::sum);
      }
      docTfMaps.add(tf);
      docFeatureSets.add(tf.keySet());

      // Update document frequency
      for (String feature : tf.keySet()) {
        documentFrequency.merge(feature, 1, Integer::sum);
      }
    }

    // --- Pass 2: Feature selection ---
    Set<String> selectedFeatures;
    if (config.getFeatureSelectionStrategy() != FeatureSelectionStrategy.NONE) {
      selectedFeatures = FeatureSelection.selectTopFeatures(
          docFeatureSets, docTfMaps, docLabels,
          config.getFeatureSelectionStrategy(), config.getMaxFeatures());
    } else {
      selectedFeatures = new HashSet<>();
      for (Set<String> fs : docFeatureSets) {
        selectedFeatures.addAll(fs);
      }
    }

    // Build final vocabulary (only selected features)
    Map<String, Integer> featureVocabulary = new LinkedHashMap<>();
    for (String feature : selectedFeatures) {
      featureVocabulary.put(feature, featureVocabulary.size() + 1);
    }

    // --- Pass 3: Compute IDF values ---
    Map<String, Double> idfValues = new HashMap<>();
    for (String feature : featureVocabulary.keySet()) {
      int df = documentFrequency.getOrDefault(feature, 0);
      idfValues.put(feature, df > 0 ? Math.log((double) totalDocs / df) : 0.0);
    }

    // --- Pass 4: Compute weighted features & collect min/max for scaling ---
    TermWeightingStrategy weighting = config.getTermWeightingStrategy();
    List<Map<Integer, Double>> docWeightedFeatures = new ArrayList<>(allSamples.size());

    // Initialize min to 0.0 for all features (absent features have implicit value 0)
    Map<Integer, Double> featureMin = new HashMap<>();
    Map<Integer, Double> featureMax = new HashMap<>();
    for (Integer idx : featureVocabulary.values()) {
      featureMin.put(idx, 0.0);
      featureMax.put(idx, 0.0);
    }

    for (Map<String, Integer> tf : docTfMaps) {
      Map<Integer, Double> weighted = new TreeMap<>();
      for (Map.Entry<String, Integer> entry : tf.entrySet()) {
        String feature = entry.getKey();
        Integer idx = featureVocabulary.get(feature);
        if (idx != null) {
          double idf = idfValues.getOrDefault(feature, 0.0);
          double value = weighting.weight(entry.getValue(), idf);
          weighted.put(idx, value);

          featureMin.merge(idx, value, Math::min);
          featureMax.merge(idx, value, Math::max);
        }
      }
      docWeightedFeatures.add(weighted);
    }

    // --- Pass 5: Scale and build SVM documents ---
    List<SvmDocument> svmDocuments = new ArrayList<>(allSamples.size());
    for (int i = 0; i < allSamples.size(); i++) {
      Map<Integer, Double> weighted = docWeightedFeatures.get(i);
      List<SvmFeature> features = buildFeatureVector(weighted, config, featureMin, featureMax);

      SvmDocument svmDoc = new TrainingSvmDocument(features);
      int categoryLabel = categoryToIndex.get(allSamples.get(i).getCategory());
      svmDoc.addClassLabel(new TrainingSvmClassLabel(categoryLabel,
          allSamples.get(i).getCategory(), 1.0));
      svmDocuments.add(svmDoc);
    }

    // --- Train SVM ---
    final SvmTrainer trainer = new SvmTrainerImpl(config.getSvmConfiguration(), "opennlp-doccat-svm");
    final Optional<SvmModel> svmModel = trainer.train(svmDocuments);

    final SvmModel trainedModel = svmModel.orElseThrow(() ->
        new RuntimeException("Training with Cross-Validation=True "
            + "does not result in a valid model."));

    return new SvmDoccatModel(trainedModel, featureVocabulary,
        indexToCategory, categoryToIndex,
        idfValues, featureMin, featureMax, config, lang);
  }

